#!/bin/bash

# 获取脚本所在目录
SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)

LOGIND_DIR="/storage/.config/logind.conf.d"
LOGIND_CONF="${LOGIND_DIR}/logind.conf"

# 确保目录存在
mkdir -p "${LOGIND_DIR}"

# 如果文件不存在，从系统默认拷贝
if [ ! -f "${LOGIND_CONF}" ]; then
    if [ -f "/etc/systemd/logind.conf" ]; then
        cp /etc/systemd/logind.conf "${LOGIND_CONF}"
    else
        # 如果 /etc 下也没有，创建一个基本的
        echo "[Login]" > "${LOGIND_CONF}"
        echo "HandlePowerKey=suspend" >> "${LOGIND_CONF}"
    fi
fi

# 获取当前的 HandlePowerKey 值
CURRENT_VAL=$(grep -E "^HandlePowerKey=" "${LOGIND_CONF}" | cut -d'=' -f2)

# 如果没有找到 HandlePowerKey（可能被注释了），我们默认认为是 suspend，或者是默认系统的行为
if [ -z "$CURRENT_VAL" ]; then
    CURRENT_VAL="suspend"
    # 把被注释的 HandlePowerKey 取消注释或者直接加一行
    if grep -q "HandlePowerKey=" "${LOGIND_CONF}"; then
        sed -i 's/^[#;]*\s*HandlePowerKey=.*/HandlePowerKey=suspend/' "${LOGIND_CONF}"
    else
        echo "HandlePowerKey=suspend" >> "${LOGIND_CONF}"
    fi
fi

# 图片 Base64 数据
POWEROFF_B64=""
SUSPEND_B64=""

TMP_IMG="/tmp/power_toggle_prompt.png"

# 切换状态并提取对应的 Base64 数据
if [ "$CURRENT_VAL" = "suspend" ]; then
    NEW_VAL="poweroff"
    echo "$POWEROFF_B64" | base64 -d > "$TMP_IMG"
else
    NEW_VAL="suspend"
    echo "$SUSPEND_B64" | base64 -d > "$TMP_IMG"
fi

# 替换配置
sed -i "s/^HandlePowerKey=.*/HandlePowerKey=${NEW_VAL}/" "${LOGIND_CONF}"

# 重启 logind 服务
systemctl restart systemd-logind

# 使用 mpv 显示提示图片 3 秒
if [ -f "$TMP_IMG" ]; then
    mpv --image-display-duration=3 --quiet "$TMP_IMG" >/dev/null 2>&1
    rm -f "$TMP_IMG"
else
    echo "Toggle to ${NEW_VAL} success. (Failed to decode image)"
fi
